/usr/bin/python3 -c 'import json,pathlib,re,subprocess; root=subprocess.run(["git","rev-parse","--show-toplevel"],stdin=subprocess.DEVNULL,capture_output=True,text=True,check=True).stdout.strip(); doc=(pathlib.Path(root)/"docs/acceptance-criteria.md").read_text(encoding="utf-8"); tickets=re.findall(r"(?ms)^##[ 	]+(T-[0-9]+) [^
]*(?:
|\Z)(.*?)(?=^##[ 	]|\Z)",doc); section=lambda body,title:(re.search(r"(?ms)^###[ 	]+"+title+r"[ 	]*
(.*?)(?=^#{1,3}[ 	]|\Z)",body) or [None,""])[1]; issues=["티켓 섹션 없음 또는 빈 문서"] if not tickets else [ticket+": "+label+" 누락" for ticket,body in tickets for label,ok in [("범위와 이유 본문",bool(re.search(r"(?m)^[ 	]*(?!#{1,6}[ 	])(?=\S)[^
]*[^\s#*+_-]",section(body,"범위와 이유"))))]+[(word+" 예시",bool(re.search(r"(?m)^[ 	]*-[ 	]+"+word+r"[ 	]+\S",section(body,"시나리오")))) for word in ("Given","When","Then")] if not ok]; print(json.dumps({"systemMessage":"AC_FORMAT 경고(차단 안 함): "+"; ".join(issues)},ensure_ascii=False)) if issues else None' 2>/dev/null || printf '%s
' '{"systemMessage":"AC_FORMAT 경고(차단 안 함): Git 루트 또는 docs/acceptance-criteria.md를 읽지 못했습니다. 경로와 읽기 권한을 확인하세요."}'
